import{_ as p,a0 as r,w as s,s as l,ao as u,I as a,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20150121 Linux FAQs with Answers--How to boot into command line on Ubuntu or Debian","title":"Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行","tag":"201501","desc":""},"relativePath":"201501/20150121 Linux FAQs with Answers--How to boot into command line on Ubuntu or Debian.md","filePath":"[post].md"}'),b={name:"201501/20150121 Linux FAQs with Answers--How to boot into command line on Ubuntu or Debian.md"};function m(d,t,_,f,x,U){const o=r("Link");return s(),l("div",null,[t[14]||(t[14]=u('<h1 id="linux-有问必答-如何在ubuntu或者debian中启动后进入命令行" tabindex="-1">Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行 <a class="header-anchor" href="#linux-有问必答-如何在ubuntu或者debian中启动后进入命令行" aria-label="Permalink to “Linux 有问必答：如何在Ubuntu或者Debian中启动后进入命令行”">​</a></h1><blockquote><p><strong>提问</strong>：我运行的是Ubuntu桌面，但是我希望启动后临时进入命令行。有什么简便的方法可以启动进入终端？</p></blockquote><p>Linux桌面自带了一个显示管理器（比如：GDM、KDM、LightDM），它们可以让计算机启动自动进入一个基于GUI的登录环境。然而，如果你要直接启动进入终端怎么办？ 比如，你在排查桌面相关的问题或者想要运行一个不需要GUI的应用程序。</p><p>注意虽然你可以通过按下Ctrl+Alt+F1到F6临时从桌面GUI切换到虚拟终端。然而，在这种情况下你的桌面GUI仍在后台运行，这不同于纯文本模式启动。</p><p>在Ubuntu或者Debian桌面中，你可以通过传递合适的内核参数在启动时启动文本模式。</p><h3 id="启动临时进入命令行" tabindex="-1">启动临时进入命令行 <a class="header-anchor" href="#启动临时进入命令行" aria-label="Permalink to “启动临时进入命令行”">​</a></h3><p>如果你想要禁止桌面GUI并临时进入一次文本模式，你可以使用GRUB菜单。</p><p>首先，打开你的电脑。当你看到初始的GRUB菜单时，按下‘e’。</p><p><img src="https://farm8.staticflickr.com/7490/16112246542_bc1875a397_z.jpg" alt=""></p><p>接着会进入下一屏，这里你可以修改内核启动选项。向下滚动到以“linux”开始的行，这里就是内核参数的列表。删除参数列表中的“quiet”和“splash”。在参数列表中添加“text”。</p><p><img src="https://farm8.staticflickr.com/7471/15493282603_8a70f70af2_z.jpg" alt=""></p><p>升级的内核选项列表看上去像这样。按下Ctrl+x继续启动。这会以详细模式启动控制台一次（LCTT译注：由于没有保存修改，所以下次重启还会进入 GUI）。</p><p><img src="https://farm8.staticflickr.com/7570/15925676530_b11af59243_z.jpg" alt=""></p><h3 id="永久启动进入命令行" tabindex="-1">永久启动进入命令行 <a class="header-anchor" href="#永久启动进入命令行" aria-label="Permalink to “永久启动进入命令行”">​</a></h3>',14)),a("p",null,[t[1]||(t[1]=n("如果你想要永久启动进入命令行，你需要",-1)),e(o,{href:"http://xmodulo.com/add-kernel-boot-parameters-via-grub-linux.html"},{default:i(()=>[...t[0]||(t[0]=[n("更新定义了内核启动参数GRUB设置",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[15]||(t[15]=u(`<p>在文本编辑器中打开默认的GRUB配置文件。</p><pre><code>$ sudo vi /etc/default/grub 
</code></pre><p>查找以GRUB_CMDLINE_LINUX_DEFAULT开头的行，并用“#”注释这行。这会禁止初始屏幕，而启动详细模式（也就是说显示详细的的启动过程）。</p><p>更改GRUB_CMDLINE_LINUX=&quot;&quot; 成：</p><pre><code>GRUB_CMDLINE_LINUX=&quot;text&quot;
</code></pre><p>接下来取消“#GRUB_TERMINAL=console”的注释。</p><p>更新后的GRUB配置看上去像下面这样。</p><p><img src="https://farm9.staticflickr.com/8673/16107564442_9345d94491_b.jpg" alt=""></p><p>最后，使用update-grub命令来基于这些更改重新生成/boot下的GRUB2配置文件。</p><pre><code>$ sudo update-grub 
</code></pre><p>这时，你的桌面应该可以从GUI启动切换到控制台启动了。可以通过重启验证。</p><p><img src="https://farm8.staticflickr.com/7518/16106378151_81ac6b5a49_b.jpg" alt=""></p><hr>`,13)),a("p",null,[t[4]||(t[4]=n("via: ",-1)),e(o,{href:"http://ask.xmodulo.com/boot-into-command-line-ubuntu-debian.html"},{default:i(()=>[...t[3]||(t[3]=[n("http://ask.xmodulo.com/boot-into-command-line-ubuntu-debian.html",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=n("译者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[5]||(t[5]=[n("geekpi",-1)])]),_:1}),t[8]||(t[8]=n(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:i(()=>[...t[10]||(t[10]=[n("Linux中国",-1)])]),_:1}),t[13]||(t[13]=n(" 荣誉推出",-1))])])}const D=p(b,[["render",m]]);export{g as __pageData,D as default};
